1	import { randomBytes } from 'node:crypto';
2	import { readdirSync } from 'node:fs';
3	import path from 'node:path';
4	import {
5	  DistillProfileSchema,
6	  loadYamlFile,
7	  type AuditEvent,
8	  type DistillProfile,
9	} from '@redutok/shared';
10	import type { AuditWriter } from './audit.js';
11	import { runGates, type GateConfig, type GateReport } from './gates.js';
12	import { fileSkeleton, languageForPath, type SkeletonLanguage } from './skeleton.js';
13	import { storeRedactedArtifact } from './redact.js';
14	import type { Store } from './store.js';
15	
16	/**
17	 * Rule-engine distillation, architecture 4.2. Profiles are yaml specs in
18	 * profiles/; every distillation decision is audited; a gate failure serves
19	 * raw. No LLM anywhere in this phase (see llm.ts for the Phase 5 hook).
20	 */
21	
22	export function loadProfiles(dir: string): Map<string, DistillProfile> {
23	  const profiles = new Map<string, DistillProfile>();
24	  for (const file of readdirSync(dir).filter((f) => f.endsWith('.yaml'))) {
25	    const profile = loadYamlFile(path.join(dir, file), DistillProfileSchema);
26	    profiles.set(profile.name, profile);
27	  }
28	  return profiles;
29	}
30	
31	function ruleConfig(profile: DistillProfile, kind: string): Record<string, unknown> {
32	  return profile.rules.find((r) => r.kind === kind)?.config ?? {};
33	}
34	
35	function verdictLine(raw: string, profile: DistillProfile): string {
36	  const v = profile.gates.verdict;
37	  if (v === undefined) return '';
38	  const hit = (patterns: string[]): boolean => patterns.some((p) => new RegExp(p, 'im').test(raw));
39	  const verdict = hit(v.primaryFail) ? 'fail' : hit(v.primaryPass) ? 'pass' : 'unknown';
40	  return `VERDICT: ${verdict}`;
41	}
42	
43	function dedupe(lines: string[]): string[] {
44	  return [...new Set(lines)];
45	}
46	
47	function relevantLines(raw: string, profile: DistillProfile): string[] {
48	  const config = ruleConfig(profile, 'relevant-lines');
49	  const pattern = new RegExp(String(config['pattern'] ?? 'error|fail'), 'i');
50	  const maxLines = Number(config['maxLines'] ?? 40);
51	  return dedupe(raw.split(/\r?\n/).filter((l) => pattern.test(l))).slice(0, maxLines);
52	}
53	
54	function buildLogDistill(raw: string, profile: DistillProfile, context: DistillContext): string {
55	  // Verdict contract only: status, first error with file:line and cause,
56	  // error count, recovery handle. Everything else is reachable via zoom.
57	  const lines = raw.split(/\r?\n/).filter((l) => l.trim() !== '');
58	  const relevant = new RegExp(profile.gates.relevantLinePattern ?? 'error|failed', 'i');
59	  const errorLines = lines.filter((l) => relevant.test(l));
60	  const verdict = verdictLine(raw, profile);
61	  if (errorLines.length === 0) {
62	    return dedupe([verdict, lines[lines.length - 1] ?? '', `[full log elided, ${zoomRef(context)}]`]).join(
63	      '\n',
64	    );
65	  }
66	  const files = new Set(
67	    errorLines.map((l) => /^([^\s(:]+)[(:]/.exec(l.trim())?.[1]).filter((f) => f !== undefined),
68	  );
69	  return [
70	    verdict,
71	    `first error: ${errorLines[0]?.trim()}`,
72	    `errors: ${errorLines.length} lines across ${files.size} files`,
73	    `[full log elided, ${zoomRef(context)}]`,
74	  ].join('\n');
75	}
76	
77	function testOutputDistill(raw: string, profile: DistillProfile): string {
78	  const summaryPattern = new RegExp(
79	    String(ruleConfig(profile, 'summary-lines')['pattern'] ?? 'Tests|Duration'),
80	  );
81	  const summary = raw.split(/\r?\n/).filter((l) => summaryPattern.test(l));
82	  const parts = [verdictLine(raw, profile), ...relevantLines(raw, profile), ...summary];
83	  return dedupe(parts.filter((p) => p !== '')).join('\n');
84	}
85	
86	async function fileSkeletonDistill(
87	  raw: string,
88	  profile: DistillProfile,
89	  context: DistillContext,
90	): Promise<string> {
91	  const lang: SkeletonLanguage =
92	    (context.filePath !== undefined ? languageForPath(context.filePath) : undefined) ?? 'ts';
93	  const allowed = (ruleConfig(profile, 'skeleton')['languages'] as string[] | undefined) ?? ['ts'];
94	  if (!allowed.includes(lang)) return '';
95	  const header = context.filePath === undefined ? [] : [`skeleton of ${context.filePath}`];
96	  const skeleton = await fileSkeleton(raw, lang);
97	  const withZoom = skeleton.replace(
98	    /^\[(\d+ import lines omitted)\]/,
99	    (_m, inner: string) => `[${inner}, ${zoomRef(context)}]`,
100	  );
101	  return [
102	    ...header,
103	    `[bodies elided, ${zoomRef(context)}]`,
104	    withZoom,
105	  ].join('\n');
106	}
107	
108	function searchResultsDistill(raw: string, profile: DistillProfile, context: DistillContext): string {
109	  const config = ruleConfig(profile, 'ranked-hits');
110	  const maxFiles = Number(config['maxFiles'] ?? 10);
111	  const maxHitsPerFile = Number(config['maxHitsPerFile'] ?? 3);
112	  const byFile = new Map<string, string[]>();
113	  let total = 0;
114	  for (const line of raw.split(/\r?\n/)) {
115	    const m = /^(.+?):(\d+):(.*)$/.exec(line);
116	    if (m === null) continue;
117	    total += 1;
118	    const hits = byFile.get(m[1] as string) ?? [];
119	    hits.push(`${m[1]}:${m[2]}: ${(m[3] as string).trim()}`);
120	    byFile.set(m[1] as string, hits);
121	  }
122	  if (total === 0) return '';
123	  const ranked = [...byFile.entries()].sort((a, b) => b[1].length - a[1].length);
124	  const shown = ranked.slice(0, maxFiles);
125	  const out = [
126	    `${total} hits in ${byFile.size} files (showing top ${shown.length} files, ${maxHitsPerFile} hits each; full set: ${zoomRef(context)})`,
127	  ];
128	  for (const [, hits] of shown) out.push(...hits.slice(0, maxHitsPerFile));
129	  return out.join('\n');
130	}
131	
132	function genericStdoutDistill(raw: string, profile: DistillProfile, context: DistillContext): string {
133	  const config = ruleConfig(profile, 'head-tail');
134	  const head = Number(config['headLines'] ?? 15);
135	  const tail = Number(config['tailLines'] ?? 10);
136	  const lines = raw.split(/\r?\n/);
137	  if (lines.length <= head + tail) return raw;
138	  const omitted = lines.length - head - tail;
139	  // Phase 5 hook: an LlmPass may summarize the omitted middle here.
140	  return [
141	    ...lines.slice(0, head),
142	    `[dcp: omitted ${omitted} middle lines, ${zoomRef(context)}]`,
143	    ...lines.slice(-tail),
144	  ].join('\n');
145	}
146	
147	export interface DistillContext {
148	  filePath?: string;
149	  /**
150	   * Artifact id the output will be stored under. Elision markers embed a
151	   * dcp__zoom reference to it so no content is dropped without a recovery
152	   * path. Absent only when a distiller is exercised outside distillArtifact.
153	   */
154	  artifactId?: string;
155	}
156	
157	function zoomRef(context: DistillContext): string {
158	  return context.artifactId === undefined
159	    ? 'zoom: dcp__zoom(handle, query?)'
160	    : `zoom: dcp__zoom("${context.artifactId}", query?)`;
161	}
162	
163	export async function runProfile(
164	  profile: DistillProfile,
165	  raw: string,
166	  context: DistillContext = {},
167	): Promise<string> {
168	  switch (profile.name) {
169	    case 'build-log':
170	      return buildLogDistill(raw, profile, context);
171	    case 'test-output':
172	      return testOutputDistill(raw, profile);
173	    case 'file-skeleton':
174	      return fileSkeletonDistill(raw, profile, context);
175	    case 'search-results':
176	      return searchResultsDistill(raw, profile, context);
177	    case 'generic-stdout':
178	      return genericStdoutDistill(raw, profile, context);
179	    default:
180	      throw new Error(`no distiller implemented for profile "${profile.name}"`);
181	  }
182	}
183	
184	export function profileGateConfig(profile: DistillProfile): GateConfig {
185	  const g = profile.gates;
186	  return {
187	    entity:
188	      g.relevantLinePattern === undefined
189	        ? undefined
190	        : {
191	            relevantLinePattern: g.relevantLinePattern,
192	            minRatio: g.entityPreservationMinRatio,
193	            limit: g.relevantLineLimit,
194	          },
195	    verdict: g.verdict,
196	    size: { maxRatio: g.sizeMaxRatio, minBytes: g.minOutputBytes },
197	  };
198	}
199	
200	export function estimateTokens(text: string): number {
201	  // Heuristic: about 4 characters per token. An estimate for handle display
202	  // only; the meter's ledger is the source of truth for real counts.
203	  return Math.ceil(text.length / 4);
204	}
205	
206	export function makeHandle(id: string, raw: string, distilled: string): string {
207	  return `[dcp:artifact ${id}, raw ${estimateTokens(raw)} tok to ${estimateTokens(distilled)} tok, zoom: dcp__zoom("${id}", query?)]`;
208	}
209	
210	export interface DistillOutcome {
211	  served: 'distilled' | 'raw';
212	  text: string;
213	  handle: string;
214	  artifactId: string;
215	  gateReport: GateReport;
216	}
217	
218	export interface DistillRequest {
219	  raw: string;
220	  profile: DistillProfile;
221	  sessionId: string;
222	  tool?: string;
223	  context?: DistillContext;
224	}
225	
226	export async function distillArtifact(
227	  store: Store,
228	  audit: AuditWriter,
229	  request: DistillRequest,
230	): Promise<DistillOutcome> {
231	  const artifactId = `a${randomBytes(3).toString('hex')}`;
232	  const distilled = await runProfile(request.profile, request.raw, {
233	    ...request.context,
234	    artifactId,
235	  });
236	  const gateConfig = profileGateConfig(request.profile);
237	  const gateReport = runGates(request.raw, distilled, gateConfig);
238	  const served = gateReport.passed ? 'distilled' : 'raw';
239	  const stored = storeRedactedArtifact(store, audit, {
240	    id: artifactId,
241	    sessionId: request.sessionId,
242	    artifactClass: request.profile.name,
243	    tool: request.tool,
244	    createdAt: new Date().toISOString(),
245	    raw: request.raw,
246	    distilled: gateReport.passed ? distilled : undefined,
