5	/**
6	 * DCP MCP server core: a pure JSON-RPC handler so tests need no stdio.
7	 * Every tool is a thin client of the sidecar with the fail-open rule from
8	 * the architecture: sidecar down means raw passthrough with a notice.
9	 */
10	
11	export interface JsonRpcRequest {
12	  jsonrpc: '2.0';
13	  id?: number | string;
14	  method: string;
15	  params?: unknown;
16	}
