31	const NOTICE = '[dcp notice: sidecar unavailable, raw passthrough]';
32	
33	const TOOLS = [
34	  {
35	    name: 'dcp__read',
36	    description:
37	      'Read a source file as a distilled skeleton (signatures and docstrings) with a zoom handle. Falls back to raw when the sidecar is down.',
38	    inputSchema: {
39	      type: 'object',
40	      properties: {
41	        file_path: { type: 'string', description: 'Absolute or repo-relative file path' },
42	      },
43	      required: ['file_path'],
44	    },
45	  },
46	  {
47	    name: 'dcp__run',
48	    description:
49	      'Run a shell command and return distilled output (verdict, first error, handles). Falls back to raw output when the sidecar is down.',
50	    inputSchema: {
51	      type: 'object',
