62	      'Search file contents under a directory and return ranked, capped hits with a zoom handle.',
63	    inputSchema: {
64	      type: 'object',
65	      properties: {
66	        pattern: { type: 'string', description: 'Regular expression' },
67	        path: { type: 'string', description: 'Directory to search, default cwd' },
68	      },
69	      required: ['pattern'],
70	    },
71	  },
72	  {
73	    name: 'dcp__zoom',
74	    description: 'Recover the raw artifact behind a dcp handle id, optionally sliced by a query.',
75	    inputSchema: {
76	      type: 'object',
77	      properties: {
78	        id: { type: 'string' },
79	        query: { type: 'string' },
