93	}
94	
95	async function distillViaSidecar(
96	  deps: McpDeps,
97	  raw: string,
98	  profile: string,
99	  filePath?: string,
100	): Promise<string> {
101	  const res = await sidecarRequest(
102	    deps.target ?? {},
103	    'POST',
104	    '/distill',
105	    { raw, profile, sessionId: deps.sessionId ?? 'mcp-session', filePath },
106	    { timeoutMs: deps.timeoutMs ?? 2500 },
107	  );
108	  if (!res.ok || res.status !== 200) return `${raw}\n${NOTICE}`;
109	  const body = res.body as { text: string; handle: string };
110	  return `${body.text}\n${body.handle}`;
111	}
112	
113	async function toolRead(deps: McpDeps, args: Record<string, unknown>): Promise<string> {
114	  const filePath = String(args['file_path']);
115	  let raw: string;
116	  try {
117	    raw = readFileSync(filePath, 'utf8');
118	  } catch (err) {
119	    return `dcp__read failed: ${err instanceof Error ? err.message : String(err)}`;
120	  }
121	  // Delta path first: unchanged files return a reference, changed files a
122	  // unified diff, and only first serves flow through the skeleton profile.
123	  const res = await sidecarRequest(
124	    deps.target ?? {},
125	    'POST',
126	    '/serve-file',
127	    { raw, path: filePath, sessionId: deps.sessionId ?? 'mcp-session' },
128	    { timeoutMs: deps.timeoutMs ?? 2500 },
129	  );
130	  if (!res.ok || res.status !== 200) return `${raw}\n${NOTICE}`;
131	  const body = res.body as { text: string; handle: string };
132	  return `${body.text}\n${body.handle}`;
133	}
