135	async function toolRun(deps: McpDeps, args: Record<string, unknown>): Promise<string> {
136	  const { execSync } = await import('node:child_process');
137	  const command = String(args['command']);
138	  let raw: string;
139	  try {
140	    raw = execSync(command, {
141	      cwd: args['cwd'] === undefined ? process.cwd() : String(args['cwd']),
142	      encoding: 'utf8',
143	      stdio: ['ignore', 'pipe', 'pipe'],
144	      timeout: 300_000,
145	    });
146	  } catch (err) {
147	    const e = err as { stdout?: string; stderr?: string; message: string };
148	    raw = `${e.stdout ?? ''}\n${e.stderr ?? ''}\ncommand failed: ${e.message}`;
149	  }
150	  const profile = /\b(tsc|build)\b/.test(command)
151	    ? 'build-log'
152	    : /\b(vitest|jest|test)\b/.test(command)
153	      ? 'test-output'
154	      : 'generic-stdout';
155	  return distillViaSidecar(deps, raw, profile);
156	}
157	
158	async function toolSearch(deps: McpDeps, args: Record<string, unknown>): Promise<string> {
159	  const { readdirSync, statSync } = await import('node:fs');
160	  const pattern = new RegExp(String(args['pattern']));
161	  const root = args['path'] === undefined ? process.cwd() : String(args['path']);
162	  const hits: string[] = [];
163	  const skip = new Set(['node_modules', '.git', 'dist', '.dcp', 'coverage']);
164	  const walk = (dir: string): void => {
165	    if (hits.length >= 2000) return;
166	    let names: string[] = [];
167	    try {
168	      names = readdirSync(dir);
169	    } catch {
170	      return;
171	    }
172	    for (const name of names) {
173	      if (skip.has(name)) continue;
174	      const full = path.join(dir, name);
175	      try {
176	        const stats = statSync(full);
177	        if (stats.isDirectory()) walk(full);
178	        else if (stats.size < 1_000_000) {
179	          const lines = readFileSync(full, 'utf8').split(/\r?\n/);
180	          lines.forEach((line, i) => {
181	            if (pattern.test(line)) hits.push(`${path.relative(root, full)}:${i + 1}:${line}`);
182	          });
183	        }
184	      } catch {
185	        continue;
186	      }
187	    }
188	  };
189	  walk(root);
190	  if (hits.length === 0) return `no matches for ${String(args['pattern'])} under ${root}`;
191	  return distillViaSidecar(deps, hits.join('\n'), 'search-results');
192	}
193	
194	async function toolZoom(deps: McpDeps, args: Record<string, unknown>): Promise<string> {
195	  const res = await sidecarRequest(
196	    deps.target ?? {},
197	    'POST',
198	    '/zoom',
199	    { id: String(args['id']), query: args['query'] === undefined ? undefined : String(args['query']) },
200	    { timeoutMs: deps.timeoutMs ?? 2500 },
201	  );
202	  if (!res.ok) return `dcp__zoom: sidecar unavailable (${res.error}); the raw artifact cannot be recovered until redutok up`;
203	  const body = res.body as { found: boolean; text: string };
204	  return body.text;
205	}
206	
207	async function toolState(deps: McpDeps): Promise<string> {
208	  const res = await sidecarRequest(deps.target ?? {}, 'GET', '/health', undefined, {
209	    timeoutMs: deps.timeoutMs ?? 1500,
210	  });
211	  if (!res.ok) return 'Sidecar: not running. Sessions degrade to raw passthrough. Start it with redutok up.';
212	  const body = res.body as { pid: number; uptimeMs: number };
213	  return `Sidecar: running, pid ${body.pid}, uptime ${Math.round(body.uptimeMs / 1000)}s.`;
214	}
215	
216	export async function handleMcpRequest(
