1	import http from 'node:http';
2	import { existsSync, rmSync, writeFileSync } from 'node:fs';
3	import path from 'node:path';
4	import type { DistillProfile } from '@redutok/shared';
5	import { AuditWriter } from './audit.js';
6	import { refreshFiles } from './codex.js';
7	import { distillArtifact, loadProfiles, zoom } from './distill.js';
8	import { serveFile } from './serve.js';
9	import { updateRollingState } from './state.js';
10	import { createLogger, type Logger } from './log.js';
11	import { openStore, type Store } from './store.js';
12	
13	/**
14	 * Sidecar daemon: localhost HTTP plus, on Windows, a named-pipe transport
15	 * (unix domain sockets are not portable here). Zero position in the request
16	 * path: if this process dies, sessions continue at full fidelity.
17	 */
18	
19	export interface DaemonOptions {
20	  /** 0 selects an ephemeral port. */
21	  port: number;
22	  /** Directory for pidfile and logs, normally <repo>/.dcp. */
23	  dcpDir: string;
24	  /** When set, also listen on \\.\pipe\<pipeName> (Windows only). */
25	  pipeName?: string;
26	  /** Directory of profiles/*.yaml; when set, /distill and /zoom are served. */
27	  profilesDir?: string;
28	}
29	
30	export interface DaemonHandle {
31	  port: number;
32	  pipePath?: string;
33	  pidfile: string;
34	  close(): Promise<void>;
35	}
36	
37	interface Engines {
38	  store: Store;
39	  audit: AuditWriter;
40	  profiles: Map<string, DistillProfile>;
41	}
42	
43	function readBody(req: http.IncomingMessage): Promise<unknown> {
44	  return new Promise((resolve, reject) => {
45	    const chunks: Buffer[] = [];
46	    req.on('data', (c: Buffer) => chunks.push(c));
47	    req.on('end', () => {
48	      try {
49	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
50	      } catch (err) {
51	        reject(err instanceof Error ? err : new Error(String(err)));
52	      }
53	    });
54	    req.on('error', reject);
55	  });
56	}
57	
58	function handler(
59	  log: Logger,
60	  engines?: Engines,
61	  onFileChange?: (filePath: string) => Promise<string[]>,
62	  onNotify?: (event: { kind: string; tool?: string; path?: string }) => Promise<void>,
63	): http.RequestListener {
64	  const startedAt = Date.now();
65	  // Active Claude Code transcript session, registered by the SessionStart and
66	  // PostToolUse hooks via /notify. The MCP server cannot know the transcript
67	  // id (Claude Code does not pass it to MCP servers), so when a session is
68	  // registered it overrides the caller-provided placeholder on every artifact
69	  // and audit event. Fallback when nothing is registered: the caller-provided
70	  // sessionId, then "unknown". Last registration wins; in-memory only, hooks
71	  // re-register on every matched tool use.
72	  const session: { activeId?: string } = {};
73	  const attributedSessionId = (provided: unknown): string =>
74	    session.activeId ?? String(provided ?? 'unknown');
75	  return (req, res) => {
76	    const url = new URL(req.url ?? '/', 'http://localhost');
77	    const respond = (status: number, body: unknown): void => {
78	      res.writeHead(status, { 'content-type': 'application/json' });
79	      res.end(JSON.stringify(body));
80	    };
81	    log.info('request', { method: req.method, path: url.pathname });
82	    if (req.method === 'POST' && url.pathname === '/serve-file') {
83	      // Delta path for dcp__read: first serve full (then distilled by the
84	      // caller's profile), later serves as diff or unchanged reference.
85	      if (engines === undefined) {
86	        respond(503, { ok: false, error: 'daemon started without a profiles directory' });
87	        return;
88	      }
89	      void readBody(req)
90	        .then(async (payload) => {
91	          const p = payload as Record<string, unknown>;
92	          const sessionId = attributedSessionId(p['sessionId']);
93	          const relPath = String(p['path'] ?? '');
94	          const raw = String(p['raw'] ?? '');
95	          const served = serveFile(engines.store, engines.audit, sessionId, relPath, raw);
96	          if (served.mode !== 'full') {
97	            respond(200, { ...served, handle: `[dcp:file ${served.ref}]` });
98	            return;
99	          }
100	          const profile = engines.profiles.get('file-skeleton');
101	          if (profile === undefined) {
102	            respond(200, { ...served, handle: `[dcp:file ${served.ref}]` });
103	            return;
104	          }
105	          const outcome = await distillArtifact(engines.store, engines.audit, {
106	            raw,
107	            profile,
108	            sessionId,
109	            tool: 'dcp__read',
110	            context: { filePath: relPath },
111	          });
112	          respond(200, {
113	            mode: 'full',
114	            ref: served.ref,
115	            text: outcome.text,
116	            handle: outcome.handle,
117	          });
118	        })
119	        .catch((err: unknown) =>
120	          respond(400, { ok: false, error: err instanceof Error ? err.message : String(err) }),
121	        );
122	      return;
123	    }
124	    if (req.method === 'POST' && (url.pathname === '/distill' || url.pathname === '/zoom')) {
125	      if (engines === undefined) {
126	        respond(503, { ok: false, error: 'daemon started without a profiles directory' });
127	        return;
128	      }
129	      void readBody(req)
130	        .then(async (payload) => {
131	          const p = payload as Record<string, unknown>;
132	          if (url.pathname === '/zoom') {
133	            respond(200, zoom(engines.store, engines.audit, String(p['id']), p['query'] as string | undefined));
134	            return;
135	          }
136	          const profile = engines.profiles.get(String(p['profile']));
137	          if (profile === undefined) {
138	            respond(400, { ok: false, error: `unknown profile "${String(p['profile'])}"` });
139	            return;
140	          }
141	          const outcome = await distillArtifact(engines.store, engines.audit, {
142	            raw: String(p['raw'] ?? ''),
143	            profile,
144	            sessionId: attributedSessionId(p['sessionId']),
145	            tool: p['tool'] as string | undefined,
146	            context: { filePath: p['filePath'] as string | undefined },
147	          });
148	          respond(200, outcome);
149	        })
150	        .catch((err: unknown) => {
151	          log.error('request failed', { path: url.pathname, error: String(err) });
152	          respond(400, { ok: false, error: err instanceof Error ? err.message : String(err) });
153	        });
154	      return;
155	    }
156	    if (req.method === 'GET' && url.pathname === '/health') {
157	      respond(200, {
158	        ok: true,
159	        pid: process.pid,
160	        uptimeMs: Date.now() - startedAt,
161	        activeSessionId: session.activeId ?? null,
162	      });
163	      return;
164	    }
165	    if (req.method === 'GET' && url.pathname === '/debug/slow') {
166	      // Test-only endpoint used by the kill-mid-request degradation test.
167	      const ms = Math.min(Number(url.searchParams.get('ms') ?? '1000'), 30_000);
168	      setTimeout(() => respond(200, { ok: true, sleptMs: ms }), ms);
169	      return;
170	    }
171	    if (req.method === 'POST' && url.pathname === '/notify') {
172	      // Metering pings and file-change notifications from PostToolUse hooks.
173	      // File changes trigger incremental codex maintenance (architecture 3.3).
174	      void readBody(req)
175	        .then(async (payload) => {
176	          log.info('notify', { payload });
177	          const p = payload as { kind?: string; tool?: string; path?: string; sessionId?: string };
178	          if (typeof p.sessionId === 'string' && p.sessionId !== '') {
179	            session.activeId = p.sessionId;
180	          }
181	          if (onNotify !== undefined) {
182	            await onNotify({ kind: p.kind ?? 'tool-use', tool: p.tool, path: p.path });
183	          }
184	          if (p.kind === 'file-change' && typeof p.path === 'string' && onFileChange !== undefined) {
185	            const reindexed = await onFileChange(p.path);
186	            respond(200, { ok: true, reindexed });
187	            return;
188	          }
189	          respond(200, { ok: true });
190	        })
191	        .catch(() => respond(400, { ok: false }));
192	      return;
193	    }
194	    if (req.method === 'POST' && url.pathname === '/shutdown') {
195	      respond(200, { ok: true, shuttingDown: true });
196	      setImmediate(() => process.emit('redutok:shutdown' as never));
197	      return;
198	    }
199	    respond(404, { ok: false, error: `no route for ${req.method} ${url.pathname}` });
200	  };
201	}
202	
203	export async function startDaemon(options: DaemonOptions): Promise<DaemonHandle> {
204	  const log = createLogger(path.join(options.dcpDir, 'sidecar.log.jsonl'));
205	  let engines: Engines | undefined;
206	  if (options.profilesDir !== undefined) {
207	    engines = {
208	      store: openStore(path.join(options.dcpDir, 'state.db')),
209	      audit: new AuditWriter(path.join(options.dcpDir, 'audit.jsonl')),
210	      profiles: loadProfiles(options.profilesDir),
211	    };
212	  }
213	  const repoRoot = path.dirname(path.resolve(options.dcpDir));
214	  const onFileChange = async (filePath: string): Promise<string[]> => {
215	    try {
216	      const rel = path.isAbsolute(filePath) ? path.relative(repoRoot, filePath) : filePath;
