1	import { LIMITS } from '@redutok/shared';
2	
3	/**
4	 * Quality gates, architecture 4.3. All deterministic, no LLM anywhere.
5	 * A distillate ships only if every configured gate passes; otherwise the raw
6	 * artifact is served and the failure audited by the caller.
7	 */
8	
9	export interface GateResult {
10	  gate: string;
11	  passed: boolean;
12	  detail: string;
13	}
14	
15	export interface GateReport {
16	  passed: boolean;
17	  results: GateResult[];
18	}
19	
20	export interface EntityGateConfig {
21	  /** Raw lines matching this regex are the conclusion-relevant region. */
22	  relevantLinePattern: string;
23	  /** Fraction of extracted entities that must appear verbatim in the distillate. */
24	  minRatio: number;
25	  /** Only the first N matching lines form the region; unset means all matches. */
26	  limit?: number;
27	}
28	
29	export interface VerdictGateConfig {
30	  primaryPass: string[];
31	  primaryFail: string[];
32	  secondaryPass: string[];
33	  secondaryFail: string[];
34	  /**
35	   * When true, the secondary extractor reads pass from the absence of any
36	   * secondaryFail marker. Still deterministic; used where success output has
37	   * no positive marker (a clean build prints nothing error-shaped).
38	   */
39	  secondaryPassIfNoFail?: boolean;
40	}
41	
42	export interface SizeGateConfig {
43	  maxRatio?: number;
44	  /** A distillate smaller than this is suspicious (extraction produced nothing). */
45	  minBytes?: number;
46	}
47	
48	export interface GateConfig {
49	  entity?: EntityGateConfig;
50	  verdict?: VerdictGateConfig;
51	  size?: SizeGateConfig;
52	}
53	
54	const ENTITY_PATTERNS: RegExp[] = [
55	  // File paths, optionally with :line (trailing :column is trimmed to :line).
56	  /[A-Za-z0-9_@./\\-]+\.[a-z]{1,6}(?::\d+)?/g,
57	  // Version strings.
58	  /\bv?\d+\.\d+\.\d+[-.\w]*\b/g,
59	  // Error codes and exception-ish identifiers.
60	  /\b(?:TS|E|ERR_)[A-Z0-9_]*\d[A-Z0-9_]*\b/g,
61	  // Quoted symbol names.
62	  /["'`]([A-Za-z_$][A-Za-z0-9_$]*)["'`]/g,
63	  // Numeric literals.
64	  /\b\d+(?:\.\d+)?\b/g,
65	];
66	
67	export function extractEntities(text: string): string[] {
68	  const entities = new Set<string>();
69	  for (const pattern of ENTITY_PATTERNS) {
70	    for (const match of text.matchAll(new RegExp(pattern.source, pattern.flags))) {
71	      entities.add(match[1] ?? (match[0] as string));
72	    }
73	  }
74	  return [...entities];
75	}
76	
77	export function entityPreservationGate(
78	  raw: string,
79	  distilled: string,
80	  config: EntityGateConfig,
81	): GateResult {
82	  const relevant = new RegExp(config.relevantLinePattern, 'i');
83	  let matches = raw.split(/\r?\n/).filter((line) => relevant.test(line));
84	  if (config.limit !== undefined) matches = matches.slice(0, config.limit);
85	  const region = matches.join('\n');
86	  const entities = extractEntities(region);
87	  if (entities.length === 0) {
88	    return { gate: 'entity-preservation', passed: true, detail: 'no entities in relevant region' };
89	  }
90	  const missing = entities.filter((e) => !distilled.includes(e));
91	  const ratio = (entities.length - missing.length) / entities.length;
92	  const passed = ratio >= config.minRatio;
93	  return {
94	    gate: 'entity-preservation',
95	    passed,
96	    detail: passed
97	      ? `${entities.length - missing.length}/${entities.length} entities preserved`
98	      : `missing entities: ${missing.slice(0, 5).join(', ')} (${missing.length} of ${entities.length})`,
99	  };
100	}
101	
102	type Verdict = 'pass' | 'fail' | 'unknown';
103	
104	function verdictFrom(text: string, passPatterns: string[], failPatterns: string[]): Verdict {
105	  const hit = (patterns: string[]): boolean => patterns.some((p) => new RegExp(p, 'im').test(text));
106	  const passed = hit(passPatterns);
107	  const failed = hit(failPatterns);
108	  if (failed && !passed) return 'fail';
109	  if (passed && !failed) return 'pass';
110	  return 'unknown';
111	}
112	
113	export function verdictFidelityGate(
114	  raw: string,
115	  distilled: string,
116	  config: VerdictGateConfig,
117	): GateResult {
118	  const primary = verdictFrom(raw, config.primaryPass, config.primaryFail);
119	  let secondary = verdictFrom(raw, config.secondaryPass, config.secondaryFail);
120	  if (secondary === 'unknown' && config.secondaryPassIfNoFail === true) {
121	    secondary = config.secondaryFail.some((p) => new RegExp(p, 'im').test(raw)) ? 'fail' : 'pass';
122	  }
123	  if (primary === 'unknown' || secondary === 'unknown' || primary !== secondary) {
124	    return {
125	      gate: 'verdict-fidelity',
126	      passed: false,
127	      detail: `extractions disagree or are inconclusive on raw: primary=${primary}, secondary=${secondary}`,
128	    };
129	  }
130	  const distilledVerdict = verdictFrom(
131	    distilled,
132	    [...config.primaryPass, ...config.secondaryPass, '\\bVERDICT: pass\\b'],
133	    [...config.primaryFail, ...config.secondaryFail, '\\bVERDICT: fail\\b'],
134	  );
135	  const passed = distilledVerdict === primary;
136	  return {
137	    gate: 'verdict-fidelity',
138	    passed,
139	    detail: passed
140	      ? `verdict ${primary} agreed by both extractions and the distillate`
141	      : `raw verdict ${primary} but distillate reads ${distilledVerdict}`,
142	  };
143	}
144	
145	export function sizeSanityGate(raw: string, distilled: string, config: SizeGateConfig): GateResult {
146	  const maxRatio = config.maxRatio ?? LIMITS.SIZE_SANITY_MAX_RATIO;
147	  const rawBytes = Buffer.byteLength(raw, 'utf8');
148	  const distilledBytes = Buffer.byteLength(distilled, 'utf8');
149	  const ratioOk = rawBytes === 0 ? false : distilledBytes / rawBytes <= maxRatio;
150	  const minOk = config.minBytes === undefined || distilledBytes >= config.minBytes;
151	  return {
152	    gate: 'size-sanity',
153	    passed: ratioOk && minOk,
154	    detail: `${distilledBytes}B of ${rawBytes}B (max ratio ${maxRatio}${
155	      config.minBytes === undefined ? '' : `, min ${config.minBytes}B`
